#include <iostream>
#include <vector>

struct Widget {
    static int copies, moves;
    Widget() = default;
    Widget(const Widget&) { ++copies; }        // 拷贝
    Widget(Widget&&) noexcept { ++moves; }     // noexcept 移动：扩容时会被优先选用
};
int Widget::copies = 0, Widget::moves = 0;

int main() {
    std::vector<Widget> v;
    v.reserve(1);
    v.push_back(Widget());   // ① 临时对象移动进容器        -> moves=1
    v.push_back(Widget());   // ② 临时对象移动进容器 + 扩容搬移旧元素(noexcept 移动) -> moves=3
    std::cout << "copies=" << Widget::copies << " moves=" << Widget::moves << '\n';
    std::cout << "结论：移动构造 noexcept 时，扩容用移动，copies 恒为 0\n";
}
